entries[146411] = { ["name"] = "Vantus Rune Technique: Tomb of Sargeras", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Tomb of Sargeras.\nCraft a Vantus Rune: Tomb of Sargeras.\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Tomb of Sargeras\nUse: Attune yourself to the energies of the targeted Tomb of Sargeras raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (10), Roseate Pigment (30)" }
entries[146412] = { ["name"] = "Vantus Rune Technique: Tomb of Sargeras", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Tomb of Sargeras more efficiently.\nReduces the materials required to craft a Vantus Rune: Tomb of Sargeras.\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Tomb of Sargeras\nUse: Attune yourself to the energies of the targeted Tomb of Sargeras raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (8), Roseate Pigment (30)" }
entries[146413] = { ["name"] = "Vantus Rune Technique: Tomb of Sargeras", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Tomb of Sargeras more efficiently.\nGreatly reduces the materials required to craft a Vantus Rune: Tomb of Sargeras.\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Tomb of Sargeras\nUse: Attune yourself to the energies of the targeted Tomb of Sargeras raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (6), Roseate Pigment (30)" }
