entries[147003] = { ["name"] = "Barbaric Mindslaver", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your healing effects have a chance to do an additional 45 healing. This occurs more often while you are at low mana.\nSell Price:" }
entries[147004] = { ["name"] = "Sea Star of the Depthmother", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: Your multi-target healing spell has a chance to grant you Ocean's Embrace, healing your nearest injured ally within 15 yds for 7 every 0.25 sec for 8 sec. Valid for healer specializations.\nSell Price:" }
entries[147005] = { ["name"] = "Chalice of Moonlight", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your healing spells have a chance to increase your Critical Strike or Haste by 22 for 12 sec. This effect grants Critical Strike during the day, or Haste during the night.\nSell Price:" }
entries[147006] = { ["name"] = "Archive of Faith", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nUse: Channel a cleansing matrix into an ally, healing them for 439 over 3 sec. Fully completing the channel also grants the ally a shield that prevents 160 damage for 10 sec. (1 Min Cooldown)\nSell Price:" }
entries[147007] = { ["name"] = "The Deceiver's Grand Design", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nUse: Mark a friendly player with Guiding Hand, healing them for 22 every 3.0 sec for 2 min. If they fall below 35% health, Guiding Hand is consumed to grant them a shield that prevents [(1 + Versatility) * 379 ] damage for 15 sec. (2 min recharge, 2 charges)\nSell Price:" }
entries[147009] = { ["name"] = "Infernal Cinders", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nEquip: Your melee attacks have a chance to deal an additional 20 Fire damage. The critical strike chance of this damage is increased by 10% for each ally within 10 yds who bears this item.\nSell Price:" }
entries[147010] = { ["name"] = "Cradle of Anguish", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nEquip: While you are above 80% health you gain 1 Strength or Agility per second, based on your specialization, stacking up to 10 times. If you fall below 50% health, this effect is lost.\nSell Price:" }
entries[147011] = { ["name"] = "Vial of Ceaseless Toxins", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nUse: Inflict 56 Shadow damage to an enemy in melee range, plus 91 damage over 20 sec. If they die while this effect is active, the cooldown of this ability is reduced by 45 sec. (1 Min Cooldown)\n\"Once more, with eeling.\"\nSell Price:" }
entries[147012] = { ["name"] = "Umbral Moonglaives", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nUse: Conjure a storm of glaives at your location, causing 18 Arcane damage every 1 sec to nearby enemies. After 8 sec the glaives shatter, causing another 49 Arcane damage to enemies in the area. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[147013] = { ["name"] = "String of Extracted Incisors", ["text"] = "Binds when picked up\nNeck\n+4 Stamina\n+ 8 Haste\n+ 6 Versatility\nSell Price:" }
entries[147014] = { ["name"] = "Locket of Splintered Souls", ["text"] = "Binds when picked up\nNeck\n+4 Stamina\n+ 6 Critical Strike\n+ 8 Mastery\nSell Price:" }
entries[147015] = { ["name"] = "Engine of Eradication", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nEquip: Your auto attacks have a chance to increase your Strength or Agility, based on your specialization, by 12 for 12 sec, and expel orbs of fel energy. Collecting an orb increases the duration of this effect by 3 sec. (12s cooldown)\nSell Price:" }
entries[147016] = { ["name"] = "Terror From Below", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nEquip: Your ranged attacks and spells have a chance to summon a behemoth from the deep to swallow your target whole, dealing 182 Nature damage split amongst you and all nearby enemies. (5s cooldown)\nSell Price:" }
entries[147017] = { ["name"] = "Tarnished Sentinel Medallion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nUse: Call upon a spectral owl to attack your target, inflicting 15 Arcane damage every 1 sec for 20 sec. Your ranged attacks and spells against the same enemy have a chance to make the owl perform an additional attack for 19 damage. (2 Min Cooldown)\nSell Price:" }
entries[147018] = { ["name"] = "Spectral Thurible", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: Your ranged attacks and spells have a chance to conjure a Spear of Anguish. After 3 sec the spear launches towards its target, dealing 73 Shadow damage to all enemies it passes through. (5s cooldown)\nSell Price:" }
entries[147019] = { ["name"] = "Tome of Unraveling Sanity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Intellect]\nUse: Deal 71 Shadow damage over 12 sec. When this effect ends or the target dies, you gain 2 Critical Strike for 12 sec plus any time remaining on the effect. (1 Min Cooldown)\nSell Price:" }
entries[147020] = { ["name"] = "Scaled Band of Servitude", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 6 Haste\n+ 8 Mastery\nSell Price:" }
