entries[147022] = { ["name"] = "Feverish Carapace", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nEquip: Taking damage has a chance to increase your Armor by 20 and cause you to reflect 6 damage as Fire when you are attacked. Lasts 10 sec.\nSell Price:" }
entries[147023] = { ["name"] = "Leviathan's Hunger", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Unleash devouring darkness upon an enemy, reducing their movement speed by 70% and inflicting 134 Shadow damage over 8 sec. You are healed for 300% of the damage dealt. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[147024] = { ["name"] = "Reliquary of the Damned", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Stamina\nUse: Surround yourself with wailing souls to prevent 50% of damage taken for 10 sec, up to [ 585 * (1 + Versatility)] total damage. The cooldown of this ability is reduced by up to 30 sec, based on the amount of damage absorbed. (2 Min, 30 Sec Cooldown)\nSell Price:" }
entries[147025] = { ["name"] = "Recompiled Guardian Module", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: Taking damage has a chance to heal you for 72 over 6 sec. When this effect expires, you and up to 4 allies within 15 yds gain a shield that prevents 21 damage for 15 sec. (7s cooldown)\nSell Price:" }
entries[147026] = { ["name"] = "Shifting Cosmic Sliver", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nEquip: Taking damage has a chance to grant you Cunning of the Deceiver, stacking up to 10 times.\nUse: Expend your Cunning to reduce the cooldown of a strong defensive ability by 10 sec per stack. If a strong defensive ability is currently active, this instead extends its duration by 1 sec per stack. Valid for tank specializations. (20 Sec Cooldown)\nSell Price:" }
